    def rotationX(x):
        x_tmp = x[0]
        x[0] = x[2]
        x[2] = x_tmp

    def distance(A, B):
        assert(0 <= A[0] < 101 and 0 <= A[1] < 101)
        assert(0 <= B[0] < 101 and 0 <= B[1] < 101)

        return math.sqrt((B[0] - A[0]) ** 2 + (B[1] - A[1]) ** 2)

    def slope(x, y, s):
        return math.atan2(s[1] - y[1], s[0] - x[0])


    def rotation(A, B, S, x1, y):

      x = (A[1] - y[1]) / (A[0] - x1) * (S[0] - x1) + x1
      y = S[1]

      if slope(A, B, S) > slope(x, y, S):
        S[0] = x
      else:
        S[1] = y  

      return S

    def new_distance(x):
