            delta_d.append([x[i], x[i + 1], distance(x[i], x[i + 1]), slope(x[i], x[i + 1], x[i + 1])])
        if(i+1 < len(x)-1):
            rotationX(delta_d[-1])
            y = [x[-1][0], x[-1][1]]
        else:
            y = [0,0]

        for i in range(len(delta_d) - 1):
            delta_d[i+1] = rotation(delta_d[i][0], delta_d[i][1], x[i+1], delta_d[i][2], y[0])

            rotationX(delta_d[i+1])

        mid = (delta_d[0][0] + delta_d[-1][0]) / 2.0
        mid_slope = 0

        for i in range(len(delta_d) - 1):
            if mid_slope > delta_d[i + 1][3]:
                delta = abs(delta_d[i + 1][0] - mid) + abs(delta_d[i + 1][2] - mid)
            if mid_slope < delta_d[i + 1][3]:
                delta += abs(delta_d[i + 1][0] - mid) + abs(delta_d[i + 1][2] - mid)

        return delta_a


    def rotation(forward, back, srcA, dstA):
        delta_angle = -1 * (-srcA[0] + dstA[0])
        rotationX(back)
        return back



